/* ==================================================================
   CUSTOMER HEADER
   Logo · menu · "My itinerary" counter · Admin · mobile menu
   ================================================================== */
/* Navigation and the announcement bar are published from the CMS
   module; when nothing is published there the house menu is used. */
const siteTestimonials = (d) => {
  const c = siteCms();
  const list = c.testimonialsOnSite ? (c.testimonials || []).filter((t) => t.status === "published" && (t.title || t.text)) : [];
  return list.length ? list.map((t) => ({ title: t.title || (t.text || "").split(/[.!?]/)[0], body: t.text, author: t.author, country: t.country })) : d;
};
const footerMenu = (k, d) => {
  const m = (siteCms().footerMenus || {})[k];
  return Array.isArray(m) && m.length ? m : d;
};
const navItems = (device) => {
  const n = siteCms().nav;
  const list = Array.isArray(n) && n.length ? n : tw;
  const auto = (it) => {
    if (it.auto === "categories") return siteCategories().filter((c) => c.visible !== false).map((c) => ({ label: c.label, to: "/marketplace?category=" + c.id }));
    if (it.auto === "destinations") return (siteCms().destinationsSite || []).filter((d) => d.status === "published").sort((a, b) => (a.order ?? 0) - (b.order ?? 0)).map((d) => ({ label: d.name, to: "/destination/" + d.slug }));
    return it.drops;
  };
  const show = (it) => !it.hidden && !(device === "desktop" && it.hideDesktop) && !(device === "mobile" && it.hideMobile);
  return list.filter(show).map((it) => { const drops = auto(it); const d2 = drops && drops.filter(show); return d2 && d2.length ? { ...it, drops: d2 } : { ...it, drops: undefined }; });
};
const announcement = () => {
  const a = siteCms().announcement;
  return announcementText(a && a.enabled && a.text ? a.text : "");
};

const NAV_LINK =
  "link-sweep flex items-center gap-1 text-[11px] font-medium uppercase tracking-[0.16em] text-ivory/75 transition-colors hover:text-ivory";
const NAV_DROP =
  "block px-5 py-2 text-[11px] font-medium uppercase tracking-[0.14em] text-ivory/70 transition-colors hover:bg-cream hover:text-gold-soft";

